CREATE TABLE courses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE terms (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL, registration_opens TIMESTAMP NOT NULL, registration_closes TIMESTAMP NOT NULL);
CREATE TABLE students (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL);
CREATE TABLE sections (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id BIGINT NOT NULL REFERENCES courses(id), term_id BIGINT NOT NULL REFERENCES terms(id), capacity INT NOT NULL, seats_taken INT NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT chk_seats CHECK (capacity > 0 AND seats_taken >= 0 AND seats_taken <= capacity));
CREATE TABLE course_prerequisites (course_id BIGINT NOT NULL REFERENCES courses(id), prerequisites_id BIGINT NOT NULL REFERENCES courses(id), PRIMARY KEY(course_id, prerequisites_id));
CREATE TABLE enrollments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id BIGINT NOT NULL REFERENCES students(id), section_id BIGINT NOT NULL REFERENCES sections(id), status VARCHAR(30) NOT NULL, enrolled_at TIMESTAMP NOT NULL, CONSTRAINT uq_student_section UNIQUE(student_id, section_id));
